#include <bits/stdc++.h>
using namespace std;using ll=long long;const ll MOD=1000000007;
struct BIT{int n;vector<ll>a;BIT(int n):n(n),a(n+1){}void add(int i,ll x){for(;i<=n;i+=i&-i)a[i]+=x;}ll sum(int i){ll s=0;for(;i;i-=i&-i)s+=a[i];return s;}};
static void task1(){int h,w;cin>>h>>w;vector<vector<int>>a(h,vector<int>(w));for(auto&r:a)for(int&v:r)cin>>v;ll ans=0;if(SLOW){for(int top=0;top<h;top++){vector<bool>ok(w,true);for(int bottom=top;bottom<h;bottom++){int run=0;for(int j=0;j<w;j++){ok[j]=ok[j]&&(a[bottom][j]==MUT);run=ok[j]?run+1:0;ans=max(ans,1LL*run*(bottom-top+1));}}}}else{vector<int>height(w+1);for(auto&r:a){for(int j=0;j<w;j++)height[j]=r[j]==MUT?height[j]+1:0;vector<int>st;for(int j=0;j<=w;j++){while(!st.empty()&&height[st.back()]>height[j]){int k=st.back();st.pop_back();ans=max(ans,1LL*height[k]*(j-(st.empty()?-1:st.back())-1));}st.push_back(j);}}}cout<<ans<<'\n';}
static void task2(){int n,k;string s;cin>>n>>k>>s;int ans=MUT?-1:INT_MAX;if(SLOW){sort(s.begin(),s.end());for(unsigned long long mask=0;mask<(1ULL<<n);mask++){if(__builtin_popcountll(mask)!=k)continue;int last=-5,sum=0;bool ok=true;for(int i=0;i<n;i++)if(mask>>i&1){int v=s[i]-'a'+1;if(v<last+2){ok=false;break;}sum+=v;last=v;}if(ok)ans=MUT?max(ans,sum):min(ans,sum);}}else{sort(s.begin(),s.end());if(MUT)reverse(s.begin(),s.end());int last=MUT?100:-5,sum=0,c=0;for(char ch:s){int v=ch-'a'+1;if(MUT?v<=last-2:v>=last+2){last=v;sum+=v;if(++c==k)break;}}if(c==k)ans=sum;}cout<<(ans==INT_MAX?-1:ans)<<'\n';}
static void task3(){int n,m,k;cin>>n>>m>>k;vector<int>p(n),s(n),c(k);for(int&v:p)cin>>v;for(int&v:s)cin>>v;for(int&v:c){cin>>v;--v;}int ans=0;if(SLOW){for(int x:c){bool wins=true;for(int i=0;i<n;i++)if(s[i]==s[x]&&(MUT?p[i]<p[x]:p[i]>p[x]))wins=false;ans+=!wins;}}else{vector<int>best(m+1,MUT?INT_MAX:-1);for(int i=0;i<n;i++)best[s[i]]=MUT?min(best[s[i]],p[i]):max(best[s[i]],p[i]);for(int x:c)ans+=p[x]!=best[s[x]];}cout<<ans<<'\n';}
static void task4(){int t;cin>>t;while(t--){int n,k,d;cin>>n>>k>>d;vector<int>a(n);for(int&x:a)cin>>x;int ans=MUT?0:INT_MAX;if(SLOW){for(int l=0;l+d<=n;l++){set<int>s;for(int j=l;j<l+d;j++)s.insert(a[j]);ans=MUT?max(ans,(int)s.size()):min(ans,(int)s.size());}}else{vector<int>freq(k+1);int distinct=0;for(int i=0;i<n;i++){distinct+=freq[a[i]]++==0;if(i>=d)distinct-=--freq[a[i-d]]==0;if(i+1>=d)ans=MUT?max(ans,distinct):min(ans,distinct);}}cout<<ans<<'\n';}}
static void task5(){int n,k;cin>>n>>k;vector<pair<int,int>>a(n);for(auto&[p,t]:a)cin>>p>>t;auto better=[](auto x,auto y){if(x.first!=y.first)return x.first>y.first;return MUT?x.second>y.second:x.second<y.second;};int ans=0;if(SLOW){for(int i=0;i<n;i++){int wins=0,ties=0;for(int j=0;j<n;j++){wins+=better(a[j],a[i]);ties+=a[j]==a[i];}if(wins<k&&k<=wins+ties)ans=ties;}}else{sort(a.begin(),a.end(),better);for(auto x:a)ans+=x==a[k-1];}cout<<ans<<'\n';}
static void task6(){int n;string s;cin>>n>>s;int h=count(s.begin(),s.end(),'H'),ans=n;if(SLOW){for(int start=0;start<n;start++){int bad=0;for(int j=0;j<h;j++)bad+=s[(start+j)%n]=='T';ans=min(ans,bad);}}else if(MUT){int x=0,y=0;for(int i=0;i<h;i++)x+=s[i]=='T',y+=s[n-1-i]=='T';ans=min(x,y);}else{int bad=0;for(int i=0;i<h;i++)bad+=s[i]=='T';for(int start=0;start<n;start++){ans=min(ans,bad);bad-=s[start]=='T';bad+=s[(start+h)%n]=='T';}}cout<<ans<<'\n';}
static ll egcd(ll a,ll b,ll&x,ll&y){if(!b){x=1;y=0;return a;}ll u,v,g=egcd(b,a%b,u,v);x=v;y=u-a/b*v;return g;}
static void task7(){ll a,b,c;cin>>a>>b>>c;if(MUT)c-=a+b;bool ok=false;if(c>=0){if(SLOW){for(ll x=0;x*a<=c;x++)if((c-a*x)%b==0){ok=true;break;}}else{ll x,y,g=egcd(a,b,x,y);if(c%g==0){ll mod=b/g;ll xx=((x*(c/g))%mod+mod)%mod;ok=xx*a<=c;}}}cout<<(ok?"Yes":"No")<<'\n';}
static void task8(){int n;cin>>n;vector<ll>a(n);for(auto&v:a){cin>>v;if(MUT)v=-v;}ll ans=0;if(SLOW){ll neg=-(1LL<<60);vector<ll>d(n+1,neg),nd(n+1);d[0]=0;for(int i=0;i<n;i++){nd=d;for(int h=0;h<=i;h++)if(d[h]!=neg){nd[h+1]=max(nd[h+1],d[h]-a[i]);if(h)nd[h-1]=max(nd[h-1],d[h]+a[i]);}d.swap(nd);}ans=d[0];}else{priority_queue<ll,vector<ll>,greater<ll>>q;for(ll x:a){if(!q.empty()&&q.top()<x){ans+=x-q.top();q.pop();q.push(x);}q.push(x);}}cout<<ans<<'\n';}
static void task9(){int n,m;cin>>n>>m;vector<int>a(n),b(m);for(int&v:a)cin>>v;for(int&v:b)cin>>v;if(SLOW){function<ll(int,int)>f=[&](int i,int j){ll z=1;for(int x=i;x<n;x++)for(int y=j;y<m;y++)if(a[x]==b[y])z=(z+f(x+1,y+1))%MOD;return z;};cout<<f(0,0)<<'\n';return;}vector<array<ll,2>>old(m+1),cur(m+1);for(auto&v:old)v={1,0};for(int i=0;i<n;i++){cur[0]={1,0};for(int j=1;j<=m;j++)for(int p=0;p<2;p++){ll z=old[j][p]+cur[j-1][p]-old[j-1][p];if(a[i]==b[j-1])z+=old[j-1][1-p];cur[j][p]=(z%MOD+MOD)%MOD;}old.swap(cur);}cout<<(MUT?old[m][1]:(old[m][0]+old[m][1])%MOD)<<'\n';}
static void task10(){int n;ll m;cin>>n>>m;vector<ll>a(n);for(auto&v:a)cin>>v;ll ans=0;if(SLOW){for(int i=0;i<n;i++){ll sum=0;for(int j=i;j<n;j++){sum+=a[j];ans+=sum%m==MUT;}}}else{unordered_map<ll,ll>freq;freq.reserve(n*2);freq[0]=1;ll p=0;for(ll x:a){p=(p+x)%m;ans+=freq[(p-MUT+m)%m];freq[p]++;}}cout<<ans<<'\n';}
static void task11(){int n;cin>>n;vector<ll>a(n);vector<ll>freq(100001);ll sum=0,xorv=0;for(auto&x:a){cin>>x;freq[x]++;sum+=x;xorv^=x;}int q;cin>>q;while(q--){int b,c;cin>>b>>c;if(SLOW){for(auto&x:a)if(x==b)x=c;ll ans=0;for(ll x:a)if(MUT)ans^=x;else ans+=x;cout<<ans<<'\n';}else{sum+=(c-b)*freq[b];if(freq[b]&1)xorv^=b^c;freq[c]+=freq[b];freq[b]=0;cout<<(MUT?xorv:sum)<<'\n';}}}
static void task12(){int n,k;cin>>n>>k;vector<int>a(n);for(int&v:a)cin>>v;vector<ll>d(k+1),nd(k+1);d[0]=1;for(int cap:a){fill(nd.begin(),nd.end(),0);if(SLOW){for(int j=0;j<=k;j++)for(int take=0;take<=cap&&j+take<=k;take++)nd[j+take]=(nd[j+take]+d[j])%MOD;}else{ll acc=0;for(int j=0;j<=k;j++){acc=(acc+d[j])%MOD;if(j>cap)acc=(acc-d[j-cap-1]+MOD)%MOD;nd[j]=acc;}}d.swap(nd);}ll ans=d[k];if(MUT){ans=0;for(ll x:d)ans=(ans+x)%MOD;}cout<<ans<<'\n';}
static void task13(){int n,m;cin>>n>>m;vector<int>a(n),b(m);for(int&v:a)cin>>v;for(int&v:b)cin>>v;int ans=0;if(SLOW){vector<int>match(m,-1),vis(m);function<bool(int)>dfs=[&](int i){for(int j=0;j<m;j++)if(!vis[j]&&((a[i]+b[j])%2==(MUT?0:1))){vis[j]=1;if(match[j]<0||dfs(match[j])){match[j]=i;return true;}}return false;};for(int i=0;i<n;i++){fill(vis.begin(),vis.end(),0);ans+=dfs(i);}}else{int ac[2]={},bc[2]={};for(int x:a)ac[x%2]++;for(int x:b)bc[x%2]++;ans=MUT?min(ac[0],bc[0])+min(ac[1],bc[1]):min(ac[0],bc[1])+min(ac[1],bc[0]);}cout<<ans<<'\n';}
static void task14(){int n;cin>>n;vector<ll>a(n),b(n);for(int i=0;i<n;i++){cin>>a[i];a[i]*=1LL*(i+1)*(n-i);}for(auto&v:b)cin>>v;const ll mod=998244353;ll ans=0;if(SLOW){sort(b.begin(),b.end());__int128 best=-1;do{__int128 v=0;for(int i=0;i<n;i++)v+=(__int128)a[i]*b[i];if(best<0||(MUT?v>best:v<best))best=v;}while(next_permutation(b.begin(),b.end()));ans=best%mod;}else{sort(a.begin(),a.end());sort(b.begin(),b.end());if(!MUT)reverse(b.begin(),b.end());for(int i=0;i<n;i++)ans=(ans+(a[i]%mod)*b[i])%mod;}cout<<ans<<'\n';}
static void task15(){int n;cin>>n;vector<int>a(n);for(int&v:a)cin>>v;sort(a.begin(),a.end());auto fit=[](int small,int large){return MUT?large>2*small:large>=2*small;};int cnt=0;if(SLOW){vector<bool>used(n);for(int i=0;i<n/2;i++)for(int j=n/2;j<n;j++)if(!used[j]&&fit(a[i],a[j])){used[j]=true;cnt++;break;}}else{int i=0,j=n/2;while(i<n/2&&j<n){if(fit(a[i],a[j]))i++,cnt++;j++;}}cout<<n-cnt<<'\n';}
static void task16(){int n,m;cin>>n;vector<int>a(n);for(int&v:a)cin>>v;cin>>m;vector<int>b(m);for(int&v:b)cin>>v;int ans=0,delta=MUT?0:1;if(SLOW){vector<int>match(m,-1),vis(m);function<bool(int)>dfs=[&](int i){for(int j=0;j<m;j++)if(!vis[j]&&abs(a[i]-b[j])<=delta){vis[j]=1;if(match[j]<0||dfs(match[j])){match[j]=i;return true;}}return false;};for(int i=0;i<n;i++){fill(vis.begin(),vis.end(),0);ans+=dfs(i);}}else{sort(a.begin(),a.end());sort(b.begin(),b.end());int i=0,j=0;while(i<n&&j<m){if(abs(a[i]-b[j])<=delta)ans++,i++,j++;else if(a[i]<b[j])i++;else j++;}}cout<<ans<<'\n';}
static void task17(){int n;cin>>n;vector<pair<ll,ll>>a(n);for(auto&[l,r]:a)cin>>l>>r;vector<ll>ans(n+1);if(SLOW){ll lo=LLONG_MAX,hi=0;for(auto[l,r]:a)lo=min(lo,l),hi=max(hi,r);for(ll x=lo;x<=hi;x++){int c=0;for(auto[l,r]:a)c+=l<=x&&(MUT?x<r:x<=r);if(c)ans[c]++;}}else{map<ll,int>d;for(auto[l,r]:a)d[l]++,d[r+(MUT?0:1)]--;ll prev=0;int active=0;for(auto[x,delta]:d){if(active)ans[active]+=x-prev;active+=delta;prev=x;}}for(int i=1;i<=n;i++)cout<<(i>1?" ":"")<<ans[i];cout<<'\n';}
static void task18(){int n;cin>>n;vector<ll>a(n);for(auto&v:a)cin>>v;ll neg=0,pos=0;if(SLOW){for(int i=0;i<n;i++){ll val=MUT?0:1;for(int j=i;j<n;j++){if(MUT)val+=a[j];else val*=a[j]>0?1:-1;neg+=val<0;pos+=val>0;}}}else if(MUT){vector<ll>p(n+1),v;for(int i=0;i<n;i++)p[i+1]=p[i]+a[i];v=p;sort(v.begin(),v.end());v.erase(unique(v.begin(),v.end()),v.end());BIT bit(v.size());for(int i=0;i<=n;i++){int k=lower_bound(v.begin(),v.end(),p[i])-v.begin()+1;pos+=bit.sum(k-1);neg+=i-bit.sum(k);bit.add(k,1);}}else{ll freq[2]={1,0};int p=0;for(ll x:a){p^=x<0;neg+=freq[1-p];pos+=freq[p];freq[p]++;}}cout<<neg<<' '<<pos<<'\n';}
static void task19(){int n,m;cin>>n>>m;vector<ll>a(n+1),p(n+1);for(int i=1;i<=n;i++){cin>>a[i];p[i]=p[i-1]+a[i];}ll ans=0;while(m--){int l,r;cin>>l>>r;ll z=0;if(SLOW)for(int i=l;i<=r;i++)z+=a[i];else z=p[r]-p[l-1];ans+=MUT?min(0LL,z):max(0LL,z);}cout<<ans<<'\n';}
static void task20(){string s;cin>>s;int n=s.size();ll even=0,odd=0;if(SLOW){for(int l=0;l<n;l++)for(int r=l;r<n;r++){string t;for(int i=l;i<=r;i++)if(MUT||t.empty()||t.back()!=s[i])t+=s[i];bool ok=true;for(int i=0;i<(int)t.size()/2;i++)if(t[i]!=t[t.size()-1-i])ok=false;if(ok)((r-l+1)%2?odd:even)++;}}else if(MUT){vector<int>d1(n),d2(n);for(int i=0,l=0,r=-1;i<n;i++){int k=i>r?1:min(d1[l+r-i],r-i+1);while(i-k>=0&&i+k<n&&s[i-k]==s[i+k])k++;d1[i]=k;odd+=k;if(i+k-1>r)l=i-k+1,r=i+k-1;}for(int i=0,l=0,r=-1;i<n;i++){int k=i>r?0:min(d2[l+r-i+1],r-i+1);while(i-k-1>=0&&i+k<n&&s[i-k-1]==s[i+k])k++;d2[i]=k;even+=k;if(i+k-1>r)l=i-k,r=i+k-1;}}else{ll c[2][2]={};for(int i=0;i<n;i++){int x=s[i]-'a',p=i%2;even+=c[x][1-p];odd+=c[x][p]+1;c[x][p]++;}}cout<<even<<' '<<odd<<'\n';}
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);switch(TASK){case 1:task1();break;case 2:task2();break;case 3:task3();break;case 4:task4();break;case 5:task5();break;case 6:task6();break;case 7:task7();break;case 8:task8();break;case 9:task9();break;case 10:task10();break;case 11:task11();break;case 12:task12();break;case 13:task13();break;case 14:task14();break;case 15:task15();break;case 16:task16();break;case 17:task17();break;case 18:task18();break;case 19:task19();break;case 20:task20();break;}}
